(function(root){'use strict';
const core=root.KANA_TRIAL_CORE,repos=root.KANA_DATA.repositories,cloud=root.KANA_CLOUD.sync,main=document.querySelector('main'),home=document.querySelector('#home'),study=document.querySelector('#studyLink'),back=document.querySelector('#back');let state=root.KANA_META.getState(),stats=state.trial||core.emptyStats(),run=null,current=null,questionAt=0;
const style=document.createElement('style');style.textContent=`
.trial-card{grid-column:1/-1;width:100%;border:1px solid #6f2635;border-radius:18px;background:linear-gradient(135deg,#2a1218,#151517);color:var(--ink);padding:19px;text-align:left;font:inherit;cursor:pointer}.trial-card:disabled{opacity:.7}.trial-card strong{display:block;font-size:1.3rem;letter-spacing:.06em}.trial-card span{display:block;color:var(--muted);margin-top:7px;line-height:1.4}.trial-screen{align-self:start;padding-top:12px}.trial-title{font-size:clamp(3rem,13vw,6.7rem);letter-spacing:-.07em;margin:8px 0}.trial-warning{color:var(--red);font-weight:900;letter-spacing:.08em}.trial-head{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:.82rem;font-weight:850;letter-spacing:.08em}.trial-threat{color:var(--red)}.trial-stimulus{font-family:"Noto Sans JP","Yu Gothic",sans-serif;font-size:clamp(2rem,10vw,4.6rem);line-height:1.45;margin:clamp(38px,9vh,80px) 0 12px;text-align:center}.trial-question{text-align:center;color:var(--muted);line-height:1.6;margin:0 0 22px}.trial-choices{display:grid;gap:9px}.trial-choices button{min-height:52px;border:1px solid var(--line);border-radius:14px;background:var(--panel);color:var(--ink);font:inherit;font-weight:800;padding:12px}.trial-choices button.correct{border-color:var(--green);color:var(--green)}.trial-choices button.wrong{border-color:var(--red);color:var(--red)}.trial-audio{display:block;margin:20px auto;border:1px solid var(--line);border-radius:15px;background:var(--panel);color:var(--ink);padding:14px 24px;font:inherit;font-weight:850}.trial-result-number{display:block;font-size:clamp(5rem,24vw,10rem);font-weight:950;line-height:1;margin-top:7vh}@media(min-width:650px){.trial-choices{grid-template-columns:repeat(3,1fr)}}`;document.head.append(style);
const card=document.createElement('button');card.type='button';card.className='trial-card';document.querySelector('.meta-panels').append(card);
const screen=document.createElement('section');screen.className='screen trial-screen';screen.hidden=true;screen.innerHTML='<div id="trialGate"><p class="eyebrow">sistema global</p><h1 class="trial-title">THE TRIAL</h1><p class="intro" id="trialGateCopy"></p><div class="challenge-record" id="trialRequirements"></div><button id="trialStart" class="challenge-start" type="button">INICIAR</button></div><div id="trialGame" hidden><div class="trial-head"><span id="trialStage"></span><span id="trialThreat" class="trial-threat"></span></div><div id="trialStimulus" class="trial-stimulus"></div><button id="trialAudio" class="trial-audio" type="button" hidden>▶ ouvir</button><p id="trialQuestion" class="trial-question"></p><div id="trialChoices" class="trial-choices"></div><p id="trialFeedback" class="feedback"></p></div><div id="trialResult" hidden><p class="eyebrow">the trial</p><strong id="trialResultNumber" class="trial-result-number"></strong><h1 id="trialResultTitle"></h1><p id="trialResultCopy" class="intro"></p><button id="trialRetry" class="challenge-start" type="button">TENTAR NOVAMENTE</button></div>';main.append(screen);const $=id=>document.getElementById(id);
function totalAttempts(){return[...Object.values(repos.mastery.getSkills()),...Object.values(repos.mastery.getVocabulary())].reduce((sum,item)=>sum+Number(item.attempts||0),0);}
function refreshState(){state=root.KANA_META.getState();stats={...core.emptyStats(),...(state.trial||{})};const status=core.unlockStatus(root.KANA_META.profile(),totalAttempts(),stats);if(status.unlocked&&!stats.unlockedAt){stats.unlockedAt=status.unlockedAt;state.trial=stats;state.achievements=state.achievements||[];if(!state.achievements.some(item=>item.id==='trial-unlocked'))state.achievements.push({id:'trial-unlocked',title:'THE TRIAL desbloqueado',at:status.unlockedAt});root.KANA_META.commit(state);}return status;}
function renderCard(){const status=refreshState();card.disabled=false;card.innerHTML=status.unlocked?`<strong>THE TRIAL</strong><span>かな。 acha que você sabe japonês. Prove. · recorde ${stats.best||0}</span>`:`<strong>🔒 THE TRIAL</strong><span>${status.evaluated||0}/7 habilidades avaliadas · mínimo ${Math.round(status.minimum||0)}/25 · ${Math.min(status.attempts||0,350)}/350 tentativas</span>`;}
function hideAll(){for(const node of main.children)node.hidden=true;home.hidden=true;screen.hidden=false;study.hidden=true;document.querySelectorAll('.header-actions .study-link').forEach(button=>button.hidden=true);back.hidden=false;}
function open(){const status=refreshState();hideAll();$('trialGate').hidden=false;$('trialGame').hidden=true;$('trialResult').hidden=true;if(status.unlocked){$('trialGateCopy').innerHTML='<span class="trial-warning">かな。 encontrou suas fraquezas.</span><br>Três rupturas encerram a prova. Cinco acertos consecutivos podem reparar uma.';$('trialRequirements').textContent=`Recorde: ${stats.best||0} · ${stats.attempts||0} runs`;$('trialStart').disabled=false;$('trialStart').textContent=stats.activeRun?'CONTINUAR':'INICIAR';$('trialStart').onclick=start;}else{$('trialGateCopy').textContent='Todas as áreas precisam existir antes que o sistema possa caçar suas fraquezas.';$('trialRequirements').textContent=`Habilidades: ${status.evaluated||0}/7 · menor eixo: ${Math.round(status.minimum||0)}/25 · tentativas: ${Math.min(status.attempts||0,350)}/350`;$('trialStart').disabled=true;$('trialStart').textContent='BLOQUEADO';}}
function freshRun(){return{startedAt:Date.now(),correct:0,errors:0,threat:0,recovery:0,counts:{},recent:[],lastTerritory:null,currentId:null,sessionId:root.KANA_PERSISTENCE.uuid()};}
function start(){run=stats.activeRun||freshRun();$('trialGate').hidden=true;$('trialResult').hidden=true;$('trialGame').hidden=false;next();saveSession();}
function select(){const profile=root.KANA_META.profile();current=run.currentId?core.QUESTIONS.find(item=>item.id===run.currentId):core.pickQuestion({profile,correct:run.correct,counts:run.counts,recent:run.recent,lastTerritory:run.lastTerritory});run.currentId=current.id;persistRun();}
function next(){select();const stage=core.stageInfo(run.correct);$('trialStage').textContent=`${stage.label} · ${current.territory.toUpperCase()}`;$('trialThreat').textContent=`RUPTURAS ${run.threat}/3`;$('trialStimulus').textContent=current.audio?'':current.prompt;$('trialQuestion').textContent=current.question;$('trialFeedback').textContent='';const audio=$('trialAudio');audio.hidden=!current.audio;if(current.audio){const once=core.stageFor(run.correct)>=3;audio.disabled=once;audio.textContent=once?'▶ reproduzindo…':'▶ ouvir novamente';const play=()=>root.KANA_AUDIO_PROVIDER?.play(current.prompt,{rate:core.stageFor(run.correct)>=3?1:.92}).catch(()=>{});audio.onclick=play;setTimeout(play,180);}const choices=$('trialChoices');choices.textContent='';current.choices.slice().sort(()=>Math.random()-.5).forEach(value=>{const button=document.createElement('button');button.textContent=value;button.onclick=()=>answer(value,button);choices.append(button);});questionAt=Date.now();}
function answer(value,button){const correct=value===current.answer,elapsed=Date.now()-questionAt;button.classList.add(correct?'correct':'wrong');$('trialChoices').querySelectorAll('button').forEach(item=>item.disabled=true);run=core.applyAnswer(run,correct);run.counts[current.territory]=Number(run.counts[current.territory]||0)+1;run.recent=[...run.recent,current.id].slice(-10);run.lastTerritory=current.territory;run.currentId=null;cloud.enqueueAttempt({sessionId:run.sessionId,item:{id:`trial:${current.id}`,written:current.prompt,reading:current.audio?current.prompt:'',category:'trial'},mode:'trial',correct,responseMs:elapsed,stat:null,meta:{ignoreMeta:true,requiresPortuguese:current.minStage<3}});$('trialFeedback').textContent=correct?'PRESSÃO SUPORTADA':`RUPTURA · ${current.answer}`;persistRun();saveSession();if(run.ended){setTimeout(()=>finish(current,value),900);return;}setTimeout(next,correct?480:900);}
function persistRun(){stats.activeRun=run;state.trial=stats;root.KANA_META.commit(state);}
function saveSession(status='active'){if(!run)return;cloud.enqueueSession({id:run.sessionId,deviceId:repos.store.read(root.KANA_PERSISTENCE.STATE_KEY,{identity:{guestId:'device'}}).identity.guestId,mode:'the-trial',territory:'global',startedAt:new Date(run.startedAt).toISOString(),endedAt:status==='completed'?new Date().toISOString():null,status,summary:{hits:run.correct,errors:run.errors,attempts:run.correct+run.errors,dateKey:new Date().toLocaleDateString('sv-SE'),excludeFromDaily:true,endgame:true,stage:core.stageFor(run.correct)}});}
function finish(defeat,given){const done=core.finishRun(stats,run,Date.now());stats=done.stats;stats.unlockedAt=state.trial?.unlockedAt||stats.unlockedAt;stats.activeRun=null;state.trial=stats;root.KANA_META.commit(state);saveSession('completed');root.dispatchEvent(new CustomEvent('kana:run-ended',{detail:{mode:'the-trial',itemId:`trial:${defeat.id}`,display:defeat.prompt,reading:defeat.audio?defeat.prompt:'',runLength:done.result.correct,answer:given,at:Date.now()}}));$('trialGame').hidden=true;$('trialResult').hidden=false;$('trialResultNumber').textContent=done.result.correct;$('trialResultTitle').textContent='A PROVA TERMINOU';$('trialResultCopy').textContent=`${done.result.errors} rupturas · estágio ${core.STAGES[done.result.stage-1].label} · recorde ${stats.best}.`;$('trialRetry').onclick=()=>{stats.activeRun=null;start();};run=null;renderCard();}
function close(){root.KANA_AUDIO_PROVIDER?.stop();screen.hidden=true;home.hidden=false;study.hidden=false;document.querySelectorAll('.header-actions .study-link').forEach(button=>button.hidden=false);back.hidden=true;}
card.addEventListener('click',open);back.addEventListener('click',event=>{if(screen.hidden)return;event.preventDefault();event.stopImmediatePropagation();close();});addEventListener('pagehide',()=>{if(run)persistRun();});addEventListener('kana:remote-restored',renderCard);addEventListener('kana:attempt-recorded',()=>setTimeout(renderCard,0));renderCard();root.KANA_TRIAL={open,getStats:()=>JSON.parse(JSON.stringify(stats))};
})(window);
